changeSet.sql:
CREATE TABLE accounts ( account_code VARCHAR(128) PRIMARY KEY, kind VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', parent_code VARCHAR(128) REFERENCES accounts (account_code), ledger_type VARCHAR(64), currency CHAR(3), is_auto_captured BOOLEAN, is_auto_settled BOOLEAN, platform_fee_fixed BIGINT, platform_fee_bps INTEGER, profile JSONB, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'), updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
CONSTRAINT chk_accounts_kind CHECK (kind IN ('PLATFORM', 'MERCHANT', 'SELLER', 'LEDGER')), CONSTRAINT chk_accounts_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')),
-- which columns each kind has CONSTRAINT chk_accounts_platform CHECK (kind <> 'PLATFORM' OR ( account_code = 'GLOBAL' AND parent_code IS NULL AND ledger_type IS NULL AND currency IS NULL AND is_auto_captured IS NULL AND is_auto_settled IS NULL AND platform_fee_fixed IS NULL AND platform_fee_bps IS NULL AND profile IS NULL)), CONSTRAINT chk_accounts_merchant CHECK (kind <> 'MERCHANT' OR ( parent_code IS NULL AND ledger_type IS NULL AND currency IS NOT NULL AND is_auto_captured IS NOT NULL AND is_auto_settled IS NOT NULL AND platform_fee_fixed >= 0 AND platform_fee_bps BETWEEN 0 AND 10000 AND profile IS NOT NULL)), CONSTRAINT chk_accounts_seller CHECK (kind <> 'SELLER' OR ( parent_code IS NOT NULL AND ledger_type IS NULL AND currency IS NULL AND is_auto_captured IS NULL AND is_auto_settled IS NULL AND platform_fee_fixed IS NULL AND platform_fee_bps IS NULL AND profile IS NULL)), CONSTRAINT chk_accounts_ledger CHECK (kind <> 'LEDGER' OR ( parent_code IS NOT NULL AND ledger_type IS NOT NULL AND currency IS NOT NULL AND is_auto_captured IS NULL AND is_auto_settled IS NULL AND platform_fee_fixed IS NULL AND platform_fee_bps IS NULL AND profile IS NULL)), CONSTRAINT chk_accounts_currency CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$') );
-- ledger lookups: one ledger account per type, owner and currency CREATE UNIQUE INDEX uq_accounts_ledger ON accounts (ledger_type, parent_code, currency) WHERE kind = 'LEDGER'; -- a merchant's sellers CREATE INDEX idx_accounts_parent ON accounts (parent_code); -- natural order for account codes (ORDER BY ... COLLATE natural_order): digit runs compare as numbers, -- so SELLER-5-2 comes before SELLER-5-10. ICU with numeric ordering (kn). CREATE COLLATION natural_order (provider = icu, locale = 'und-u-kn-true');
